title:
* TabNav 컴포넌트 - 웹 접근성을 준수한 탭 인터페이스
* 
* @접근성기능
* 1. ARIA Roles & Properties
* - role="tablist": 탭 목록을 나타냄
* - role="tab": 개별 탭을 나타냄
* - aria-selected: 현재 선택된 탭 상태
* - aria-controls: 탭이 제어하는 패널 ID
* - aria-label: 탭 메뉴의 설명
* 
* 2. 키보드 접근성
* - ArrowLeft: 이전 탭으로 이동
* - ArrowRight: 다음 탭으로 이동
* - Home: 첫 번째 탭으로 이동
* - End: 마지막 탭으로 이동
* - tabIndex: 키보드 포커스 관리
* 
* @JavaScript
* - useRef: 탭 요소들의 참조를 관리
* - useState: 탭 포커스 상태 관리
* - useEffect: 키보드 이벤트 리스너 설정
* - handleKeyDown: 키보드 내비게이션 로직
* - handleTabClick: 탭 클릭 이벤트 처리
* 

import { cn } from '@/utils/cn'
import { cva } from 'class-variance-authority'
import { forwardRef, useEffect, useRef, useState } from 'react'
import Button from '../button/Button'
import { motion } from 'framer-motion'
import clsx from 'clsx'

const tabListVariants = cva('flex', {
  variants: {
    variant: {
      underline: 'gap-6 border-gray-200',
      bordered: 'border-b-gray-200',
    },
  },
  defaultVariants: {
    variant: 'underline',
  },
})

const tabItemVariants = cva('relative', {
  variants: {
    variant: {
      underline: 'cursor-pointer pb-[1.5rem]',
      bordered: 'mr-[-1px] inline-block border border-b-0 border-gray-200',
    },
  },
  defaultVariants: {
    variant: 'underline',
  },
})

export interface Tab {
  id: number
  label: number | string
}

export interface TabNavProps {
  tabs: Tab[]
  activeTab: number
  onActiveTab: (id: number) => void
  className?: string
  plusButton?: () => JSX.Element
  variant?: 'underline' | 'bordered' // 스타일 variant 추가
}

const TabNav = forwardRef<HTMLDivElement, TabNavProps>(
  (
    {
      tabs,
      activeTab,
      onActiveTab,
      className,
      plusButton,
      variant = 'underline',
      ...props
    },
    ref,
  ) => {
    const tabRefs = useRef<(HTMLButtonElement | null)[]>([])
    const [tabFocus, setTabFocus] = useState<number>(0)

    useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
        const target = e.target as HTMLElement
        if (!target.matches('[role="tab"]')) return

        let newFocus = tabFocus

        switch (e.key) {
          case 'ArrowLeft':
            newFocus = tabFocus === 0 ? tabs.length - 1 : tabFocus - 1
            break
          case 'ArrowRight':
            newFocus = tabFocus === tabs.length - 1 ? 0 : tabFocus + 1
            break
          case 'Home':
            newFocus = 0
            break
          case 'End':
            newFocus = tabs.length - 1
            break
          default:
            return
        }

        setTabFocus(newFocus)
        tabRefs.current[newFocus]?.focus()
        onActiveTab(tabs[newFocus].id)
        e.preventDefault()
      }

      const tabList = document.querySelector('[role="tablist"]')
      tabList?.addEventListener('keydown', handleKeyDown as EventListener)

      return () => {
        tabList?.removeEventListener('keydown', handleKeyDown as EventListener)
      }
    }, [tabs, tabFocus, onActiveTab])

    const handleTabClick = (tabId: number, index: number) => {
      onActiveTab(tabId)
      setTabFocus(index)
    }

    return (
      <div ref={ref} className={cn('border-b', className)} {...props}>
        <ul
          role="tablist"
          aria-label="탭 메뉴"
          className={tabListVariants({ variant })}
        >
          {tabs.map((tab, index) => (
            <li
              key={tab.id}
              className={cn(
                tabItemVariants({ variant }),
                variant === 'bordered' &&
                  activeTab === tab.id &&
                  'font-bold after:absolute after:bottom-[-1px] after:block after:h-[1px] after:w-full after:bg-white',
                variant === 'bordered' && activeTab !== tab.id && 'bg-gray-50',
              )}
            >
              <Button
                ref={(el) => (tabRefs.current[index] = el)}
                role="tab"
                aria-selected={activeTab === tab.id}
                aria-controls={`panel-${tab.id}`}
                id={`tab-${tab.id}`}
                tabIndex={activeTab === tab.id ? 0 : -1}
                onClick={() => handleTabClick(tab.id, index)}
                className={clsx(
                  'text-2xl ',
                  variant === 'bordered' && 'inline-block h-20 px-16 align-top',
                  activeTab === tab.id
                    ? 'font-bold text-purple-800'
                    : 'text-black',
                  className,
                )}
              >
                {tab.label}
              </Button>
              {variant === 'underline' && tab.id === activeTab && (
                <motion.div
                  className="absolute bottom-0 left-0 right-0 h-[3px] bg-purple-800"
                  layoutId="underline"
                />
              )}
            </li>
          ))}
          {plusButton && plusButton()}
        </ul>
      </div>
    )
  },
)

TabNav.displayName = 'TabNav'

export default TabNav

